import React, { HTMLProps, useImperativeHandle, useRef, useState } from 'react';
import InputWrapper, { InputWrapperProps } from '../InputWrapper';
import { StyledDiv, StyledIcon, StyledTextArea } from './TextArea.styles';

export interface TextAreaProps
  extends Omit<HTMLProps<HTMLTextAreaElement>, 'children' | 'size' | 'css'>,
    Omit<InputWrapperProps, 'children' | 'counter' | 'maxCounter'> {
  width?: string | number;
}

export const TextArea = React.forwardRef(
  (
    {
      characterCounter,
      hint,
      label,
      legend,
      required,
      optionalText = '(Optional)',
      hasError,
      disabled = false,
      errorText,
      labelProps,
      value: valueFromProps,
      onChange: onChangeFromProps,
      defaultValue,
      placeholder = 'Placeholder text',
      id,
      width,
      ...otherProps
    }: TextAreaProps,
    forwardedRef: React.ForwardedRef<HTMLTextAreaElement>
  ): JSX.Element => {
    const isControlled = valueFromProps !== undefined;
    const hasDefaultvalue = defaultValue !== undefined;
    const [value, setValue] = useState(() => (hasDefaultvalue ? defaultValue?.toString() : ''));
    const mappedValue = isControlled ? valueFromProps?.toString() : value;

    const innerRef = useRef<HTMLTextAreaElement | null>(null);
    useImperativeHandle(forwardedRef, () => innerRef?.current as HTMLTextAreaElement);

    const mappedPlaceholder = !label && !required ? `${placeholder} ${optionalText}` : placeholder;

    const onChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      if (onChangeFromProps && typeof onChangeFromProps === 'function') {
        onChangeFromProps(e);
        if (!isControlled) setValue(e.target.value);
        return;
      }
      setValue(e.target.value);
    };

    return (
      <InputWrapper
        labelProps={{ ...labelProps, htmlFor: id }}
        label={label}
        hint={hint}
        legend={legend}
        hasError={hasError}
        disabled={disabled}
        required={required}
        errorText={errorText}
        optionalText={optionalText}
        characterCounter={characterCounter}
        counter={mappedValue?.length}
        width={width}
        maxCounter={otherProps.maxLength}
      >
        <StyledDiv>
          <StyledTextArea
            {...otherProps}
            ref={innerRef}
            value={mappedValue}
            onChange={onChange}
            hasError={hasError}
            placeholder={mappedPlaceholder?.trim()}
            id={id}
            disabled={disabled}
          />
          <StyledIcon size="large" />
        </StyledDiv>
      </InputWrapper>
    );
  }
);

export default TextArea;
